def create_encryption_key(string1):
    chars=list(set(list(string1)))
    keydict={}
    taken =[]
    for each in chars:
        while(1):
            r=random.choice(chars)
            if(r not in taken) :
                keydict[each]= r
                taken.append(r)
                break
    return(keydict)

